questions.evidence:
registers:                     # in the shell window: absolute address = 0x80 + offset
  shell: shell/PROTOCOL.md (version 1.0)
  map:
    - {offset: 0x00, name: COUNT,   access: RW, reset: 0x0000, bits: "[15:0] counter; write sets it; [31:16] read 0"}
    - {offset: 0x01, name: DUTY,    access: RW, reset: 0x40,   bits: "[7:0] PWM duty when DUTY_SRC = 0; [31:8] read 0"}
    - {offset: 0x02, name: CTRL,    access: RW, reset: 0x2,    bits: "[0] DUTY_SRC (1 = switches SW[7:0]); [1] DISPLAY_EN; [31:2] read 0"}
    - {offset: 0x03, name: INPUTS,  access: RO, reset: null,   bits: "[15:0] SW (synchronised); [16] BTNU, [17] BTND, [18] BTNC (debounced levels)"}
    - {offset: 0x04, name: PRESSES, access: RO, reset: 0,      bits: "[7:0] up presses, [15:8] down, [23:16] clear; each wraps at 256"}
